import { REQUEST_ID_HEADER } from "../constants/http";

/**
 * Determine the request id for a request/response pair.
 *
 * A correlation id supplied by the caller is preserved (and echoed back)
 * so that a distributed trace can be followed across services. When it is
 * absent or malformed a new id is generated by the request-id middleware.
 */
export const getRequestId = (
    headers: Record<string, unknown>
): string | undefined => {
    const value = headers[REQUEST_ID_HEADER];

    if (typeof value === "string" && value.trim().length > 0) {
        return value.trim();
    }

    return undefined;
};

export const pickRequestId = (
    req: { id?: string; headers: Record<string, unknown> },
    res: { getHeader: (name: string) => number | string | string[] | undefined }
): string | undefined => {
    return (
        req.id ??
        getRequestId(req.headers) ??
        (res.getHeader(REQUEST_ID_HEADER) as string | undefined)
    );
};
